/* ParksMap — a relief model with every national park in one region marked on it.
 *
 * The page shows ONE region at a time (the lower 48, Alaska or Hawaii), each at full
 * width, so a phone never has to shrink one to fit another beside it.
 *
 * Everything drawn is real data, generated by tools/build-parks.mjs:
 *   - the ground is a measured elevation grid (public/outdoors/relief-<id>.png), inked
 *     in flat bands with contour lines like a 1930s park screenprint
 *   - state lines are Natural Earth boundaries draped on that ground
 *   - park outlines are the Park Service's own boundary records
 *   - each marker stands on a park's own National Park Service coordinate
 * ONE projection per region (`frame.project`) places all of it. lat first.
 *
 * Stylised, and said so on the page: heights are exaggerated, and snow is drawn above a
 * snowline that drops with latitude. Neither is a measurement.
 *
 * The model sits on a dark drafting table and casts a real shadow on it. One bar moves
 * the light from afternoon through dusk to night.
 *
 * The canvas is a view, not the only way in: the page's index reaches every park with a
 * 44px target and a keyboard, including the island parks that have no model.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { OrbitControls, Html } from '@react-three/drei'
import { EffectComposer, N8AO, TiltShift2, Vignette, Noise } from '@react-three/postprocessing'
import * as THREE from 'three'
import { RELIEFS } from './data/usRelief'

const W = 100
const RISE = 5.2 // world units at the region's maxMetres: exaggerated so relief reads
const DRAMA = 1.2 // > 1 lifts the high country more than the plains
const BANDS = 16 // ink layers; spaced so lowlands get as many as the high country
/* 0 to 1: how far up the land the ink has been laid. One map per page, so one shared uniform. */
const REVEAL = { value: 1 }

function makeFrame(r) {
  const b = r.bounds
  const midLat = (b.north + b.south) / 2
  const aspect = ((b.east - b.west) * Math.cos((midLat * Math.PI) / 180)) / (b.north - b.south)
  const D = W / aspect
  return {
    ...r,
    D,
    /** lat first. Returns [x, z] on the ground plane. */
    project: (lat, lng) => [
      ((lng - b.west) / (b.east - b.west)) * W - W / 2,
      ((b.north - lat) / (b.north - b.south)) * D - D / 2,
    ],
    contains: (lat, lng) => lng > b.west && lng < b.east && lat > b.south && lat < b.north,
  }
}
const FRAMES = Object.fromEntries(RELIEFS.map((r) => [r.id, makeFrame(r)]))
export const REGIONS = RELIEFS.map(({ id, label }) => ({ id, label }))

export function shortName(park) {
  return park.name.replace(/ National Parks?( (&|and) Preserve)?$| National and State Parks$/, '')
}

/* ---------- the relief grid ---------- */
function useRelief(frame) {
  const [relief, setRelief] = useState(null)
  useEffect(() => {
    let live = true
    const { cols, rows, bounds } = frame
    const img = new window.Image()
    img.onload = () => {
      if (!live) return
      const c = document.createElement('canvas')
      c.width = cols
      c.height = rows
      const g = c.getContext('2d', { willReadFrequently: true })
      g.drawImage(img, 0, 0)
      const px = g.getImageData(0, 0, cols, rows).data
      const raw = new Float32Array(cols * rows)
      const land = new Uint8Array(cols * rows)
      for (let i = 0; i < cols * rows; i++) {
        raw[i] = px[i * 4] / 255
        land[i] = px[i * 4 + 1] > 50 && px[i * 4 + 1] < 150 ? 1 : 0 // the United States only
      }
      // The file stores height in 256 steps. One light blur removes the terracing that
      // leaves on steep ground, without moving any summit.
      const elev = new Float32Array(cols * rows)
      for (let r = 0; r < rows; r++) {
        for (let cx = 0; cx < cols; cx++) {
          let sum = 0
          let wsum = 0
          for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
              const rr = r + dr
              const cc = cx + dc
              if (rr < 0 || cc < 0 || rr >= rows || cc >= cols) continue
              const wgt = (dr === 0 ? 2 : 1) * (dc === 0 ? 2 : 1)
              sum += raw[rr * cols + cc] * wgt
              wsum += wgt
            }
          }
          elev[r * cols + cx] = sum / wsum
        }
      }
      const lift = (t) => Math.pow(t, DRAMA) * RISE
      const groundAt = (lat, lng) => {
        const cx = Math.round(((lng - bounds.west) / (bounds.east - bounds.west)) * (cols - 1))
        const ry = Math.round(((bounds.north - lat) / (bounds.north - bounds.south)) * (rows - 1))
        const i = Math.max(0, Math.min(rows - 1, ry)) * cols + Math.max(0, Math.min(cols - 1, cx))
        return lift(elev[i])
      }
      setRelief({ elev, land, lift, groundAt })
    }
    img.src = frame.src
    return () => {
      live = false
    }
  }, [frame])
  return relief
}

/* Polylines of [lng, lat] from a JSON file, draped on the ground as line segments. */
function drape(frame, relief, runs, lift) {
  const pos = []
  for (const run of runs) {
    if (!frame.contains(run[0][1], run[0][0])) continue
    for (let i = 1; i < run.length; i++) {
      for (const [lng, lat] of [run[i - 1], run[i]]) {
        const [x, z] = frame.project(lat, lng)
        pos.push(x, relief.groundAt(lat, lng) + lift, z)
      }
    }
  }
  return pos
}
function lineGeometry(pos) {
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(pos), 3))
  return g
}

function useStateLines(frame, relief) {
  const [geometry, setGeometry] = useState(null)
  useEffect(() => {
    if (!relief || !frame.linesSrc) return undefined
    let live = true
    window
      .fetch(frame.linesSrc)
      .then((r) => (r.ok ? r.json() : []))
      .then((runs) => {
        const pos = drape(frame, relief, runs, 0.035)
        if (live && pos.length) setGeometry(lineGeometry(pos))
      })
      .catch(() => {})
    return () => {
      live = false
    }
  }, [frame, relief])
  return geometry
}

/* Each park's real outline, from the Park Service's boundary service. */
function useParkBounds(frame, relief) {
  const [layers, setLayers] = useState(null)
  useEffect(() => {
    if (!relief) return undefined
    let live = true
    window
      .fetch(frame.boundsSrc)
      .then((r) => (r.ok ? r.json() : {}))
      .then((byPark) => {
        if (!live) return
        const all = []
        const byCode = {}
        for (const [code, rings] of Object.entries(byPark)) {
          const pos = drape(frame, relief, rings, 0.05)
          if (!pos.length) continue
          byCode[code] = lineGeometry(pos)
          for (const v of pos) all.push(v)
        }
        if (all.length) setLayers({ all: lineGeometry(all), byCode })
      })
      .catch(() => {})
    return () => {
      live = false
    }
  }, [frame, relief])
  return layers
}

/* ---------- the ink ---------- */
/* Dusk Field Guide palette, exclusive to /outdoors. Stops are in band space (0 = sea level). */
const INK = [
  [0.0, '#1F3A2C'],
  [0.1, '#2F5239'],
  [0.22, '#4E7148'],
  [0.36, '#7C8A52'],
  [0.5, '#A8794B'],
  [0.64, '#B98657'],
  [0.8, '#A9957C'],
  [1.0, '#B8AE9F'],
].map(([t, hex]) => [t, new THREE.Color(hex)])

function useRamp() {
  return useMemo(() => {
    const n = 128
    const data = new Uint8Array(n * 4)
    const c = new THREE.Color()
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1)
      let k = 1
      while (k < INK.length - 1 && t > INK[k][0]) k++
      const [t0, c0] = INK[k - 1]
      const [t1, c1] = INK[k]
      c.copy(c0).lerp(c1, Math.min(1, Math.max(0, (t - t0) / (t1 - t0))))
      c.convertLinearToSRGB()
      data[i * 4] = Math.round(c.r * 255)
      data[i * 4 + 1] = Math.round(c.g * 255)
      data[i * 4 + 2] = Math.round(c.b * 255)
      data[i * 4 + 3] = 255
    }
    const tex = new THREE.DataTexture(data, n, 1, THREE.RGBAFormat)
    tex.colorSpace = THREE.SRGBColorSpace
    tex.minFilter = tex.magFilter = THREE.LinearFilter
    tex.needsUpdate = true
    return tex
  }, [])
}

function useTerrain(frame, relief, step) {
  return useMemo(() => {
    const { cols, rows, D } = frame
    const nc = Math.floor((cols - 1) / step) + 1
    const nr = Math.floor((rows - 1) / step) + 1
    const pos = new Float32Array(nc * nr * 3)
    const elev = new Float32Array(nc * nr)
    const land = new Float32Array(nc * nr)
    for (let r = 0; r < nr; r++) {
      for (let c = 0; c < nc; c++) {
        const src = r * step * cols + c * step
        const i = r * nc + c
        const isLand = relief.land[src] === 1
        const t = isLand ? relief.elev[src] : 0
        pos[i * 3] = ((c * step) / (cols - 1)) * W - W / 2
        pos[i * 3 + 1] = relief.lift(t)
        pos[i * 3 + 2] = ((r * step) / (rows - 1)) * D - D / 2
        elev[i] = t
        let sum = 0
        let n = 0
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            const rr = r * step + dr
            const cc = c * step + dc
            if (rr < 0 || cc < 0 || rr >= rows || cc >= cols) continue
            sum += relief.land[rr * cols + cc]
            n++
          }
        }
        land[i] = sum / n // a 3x3 mean, so the shader's cut at 0.5 runs smoothly between cells
      }
    }
    const idx = new Uint32Array((nc - 1) * (nr - 1) * 6)
    let k = 0
    for (let r = 0; r < nr - 1; r++) {
      for (let c = 0; c < nc - 1; c++) {
        const a = r * nc + c
        const b = a + 1
        const d = a + nc
        const e = d + 1
        // Only the United States is drawn: the region is a cut-out model.
        if (land[a] + land[b] + land[d] + land[e] < 0.01) continue
        idx[k++] = a
        idx[k++] = d
        idx[k++] = b
        idx[k++] = b
        idx[k++] = d
        idx[k++] = e
      }
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    g.setAttribute('aElev', new THREE.BufferAttribute(elev, 1))
    g.setAttribute('aLand', new THREE.BufferAttribute(land, 1))
    g.setIndex(new THREE.BufferAttribute(idx.subarray(0, k), 1))
    g.computeVertexNormals()
    return g
  }, [frame, relief, step])
}

const VERT_HEAD =
  'attribute float aElev;\nattribute float aLand;\nvarying float vElev;\nvarying float vLand;\nvarying vec3 vAt;'
const FRAG_HEAD =
  'uniform sampler2D uRamp;\nuniform float uBands;\nuniform float uReveal;\nuniform float uDepth;\nuniform float uNorthLat;\nuniform float uSouthLat;\nuniform float uMaxM;\nvarying float vElev;\nvarying float vLand;\nvarying vec3 vAt;'
const FRAG_INK = [
  'if (vLand < 0.5) discard;', // interpolated, so the coast is a clean line
  'float e = pow(max(vElev, 0.0), 0.6) * uBands + 0.5;',
  'float band = floor(e) / uBands;',
  'vec3 ink = texture2D(uRamp, vec2(clamp(band, 0.004, 0.996), 0.5)).rgb;',
  'float f = fract(e);',
  'float w = max(fwidth(e), 0.00001);',
  'float line = 1.0 - smoothstep(w * 0.6, w * 1.6, min(f, 1.0 - f));',
  'line *= 1.0 - smoothstep(0.3, 0.95, w);', // on steep ground the lines would pile into a smear
  'vec3 col = mix(ink, ink * 0.45, line * 0.5);',
  // snow: above a line that drops with latitude, with a broken edge
  'float lat = mix(uNorthLat, uSouthLat, clamp(vAt.z / uDepth + 0.5, 0.0, 1.0));',
  'float snowLine = clamp(3900.0 - (lat - 25.0) * 62.0, 900.0, 4300.0) / uMaxM;',
  'float grain = fract(sin(dot(floor(vAt.xz * 7.0), vec2(12.9898, 78.233))) * 43758.5453);',
  'float snow = smoothstep(snowLine - 0.012, snowLine + 0.05, vElev + (grain - 0.5) * 0.03);',
  'col = mix(col, vec3(0.93, 0.95, 0.98), snow * 0.94);',
  'float laid = smoothstep(0.0, 0.07, uReveal * 1.12 - band);',
  'vec3 paper = texture2D(uRamp, vec2(0.004, 0.5)).rgb;',
  'diffuseColor.rgb = mix(paper, col, laid);',
].join('\n')

function Terrain({ frame, relief, step, still, lines, parkBounds, activeCode }) {
  const geometry = useTerrain(frame, relief, step)
  const ramp = useRamp()
  const ref = useRef()
  const t0 = useRef(null)
  const material = useMemo(() => {
    const m = new THREE.MeshStandardMaterial({ roughness: 1, metalness: 0, color: '#ffffff' })
    m.onBeforeCompile = (shader) => {
      shader.uniforms.uRamp = { value: ramp }
      shader.uniforms.uBands = { value: BANDS }
      shader.uniforms.uReveal = REVEAL
      shader.uniforms.uDepth = { value: frame.D }
      shader.uniforms.uNorthLat = { value: frame.bounds.north }
      shader.uniforms.uSouthLat = { value: frame.bounds.south }
      shader.uniforms.uMaxM = { value: frame.maxMetres }
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', '#include <common>\n' + VERT_HEAD)
        .replace(
          '#include <begin_vertex>',
          '#include <begin_vertex>\nvElev = aElev;\nvLand = aLand;\nvAt = position;'
        )
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', '#include <common>\n' + FRAG_HEAD)
        .replace('#include <color_fragment>', '#include <color_fragment>\n' + FRAG_INK)
    }
    return m
  }, [ramp, frame])
  useFrame(({ clock }) => {
    if (!ref.current || still) return
    if (t0.current === null) t0.current = clock.elapsedTime
    const p = Math.min(1, (clock.elapsedTime - t0.current) / 2.2)
    ref.current.scale.y = 0.02 + 0.98 * (1 - Math.pow(1 - p, 3)) // the land rises, once
    // ...and the ink follows it up, lowlands first, summits last
    const q = Math.min(1, Math.max(0, (clock.elapsedTime - t0.current - 0.5) / 2.8))
    REVEAL.value = q * q * (3 - 2 * q)
  })
  return (
    <group ref={ref} scale={[1, still ? 1 : 0.02, 1]}>
      <mesh geometry={geometry} material={material} castShadow receiveShadow />
      {lines && (
        <lineSegments geometry={lines}>
          <lineBasicMaterial color="#F4EAD4" transparent opacity={0.17} depthWrite={false} />
        </lineSegments>
      )}
      {parkBounds && (
        <lineSegments geometry={parkBounds.all}>
          <lineBasicMaterial
            color="#F2B45A"
            transparent
            opacity={0.6}
            depthWrite={false}
            toneMapped={false}
          />
        </lineSegments>
      )}
      {parkBounds && activeCode && parkBounds.byCode[activeCode] && (
        <lineSegments geometry={parkBounds.byCode[activeCode]} renderOrder={5}>
          <lineBasicMaterial color="#FFE9BE" depthTest={false} toneMapped={false} />
        </lineSegments>
      )}
    </group>
  )
}

/* The model has thickness: the same outline, stacked flat and dark beneath the surface. */
const SLAB_VERT =
  'attribute float aLand;\nvarying float vLand;\nvoid main() {\n  vLand = aLand;\n  gl_Position = projectionMatrix * modelViewMatrix * vec4(position.x, 0.0, position.z, 1.0);\n}'
const SLAB_FRAG =
  'uniform vec3 uColor;\nvarying float vLand;\nvoid main() {\n  if (vLand < 0.5) discard;\n  gl_FragColor = vec4(uColor, 1.0);\n}'
const STRATA = [
  [-0.16, '#2A2018'],
  [-0.32, '#211912'],
  [-0.48, '#18120D'],
  [-0.64, '#100C09'],
]
function Slab({ frame, relief }) {
  const geometry = useTerrain(frame, relief, 2)
  const materials = useMemo(
    () =>
      STRATA.map(
        ([, colour]) =>
          new THREE.ShaderMaterial({
            vertexShader: SLAB_VERT,
            fragmentShader: SLAB_FRAG,
            uniforms: { uColor: { value: new THREE.Color(colour) } },
          })
      ),
    []
  )
  return STRATA.map(([y], i) => (
    <mesh key={y} geometry={geometry} material={materials[i]} position={[0, y, 0]} />
  ))
}

/* ---------- the light ---------- */
const hex = (h) => new THREE.Color(h)
/* s: 0 afternoon · 0.42 golden hour · 0.68 dusk · 1 night.  `table` is the surface the
 * model sits on; `wash` is how strongly the low sun warms its western side. */
const KEYS = [
  {
    s: 0,
    el: 52,
    sun: hex('#FFF4E2'),
    sunI: 3.2,
    hemiSky: hex('#D6E2EE'),
    hemiGround: hex('#3A4A3F'),
    hemiI: 0.95,
    table: hex('#25322C'),
    wash: 0,
    dark: 0,
  },
  {
    s: 0.42,
    el: 20,
    sun: hex('#FFCB8E'),
    sunI: 3.2,
    hemiSky: hex('#B4C2D6'),
    hemiGround: hex('#1C2620'),
    hemiI: 0.7,
    table: hex('#1B2521'),
    wash: 0.75,
    dark: 0.4,
  },
  {
    s: 0.68,
    el: 10,
    sun: hex('#FF9655'),
    sunI: 2.5,
    hemiSky: hex('#8497B8'),
    hemiGround: hex('#0F1714'),
    hemiI: 0.62,
    table: hex('#121A18'),
    wash: 1,
    dark: 0.8,
  },
  {
    s: 1,
    el: 10,
    sun: hex('#FF9655'),
    sunI: 0,
    hemiSky: hex('#5E78A8'),
    hemiGround: hex('#070B10'),
    hemiI: 0.36,
    table: hex('#090E12'),
    wash: 0,
    dark: 1,
  },
]
const MOON = hex('#A9C1EA')

function atmosphere(s) {
  let i = 1
  while (i < KEYS.length - 1 && s > KEYS[i].s) i++
  const a = KEYS[i - 1]
  const b = KEYS[i]
  const t = Math.min(1, Math.max(0, (s - a.s) / (b.s - a.s)))
  const mix = (k) => a[k] + (b[k] - a[k]) * t
  const col = (k) => a[k].clone().lerp(b[k], t)
  const el = (mix('el') * Math.PI) / 180
  return {
    sunDir: new THREE.Vector3(-Math.cos(el) * 0.86, Math.sin(el), Math.cos(el) * 0.5).normalize(),
    sun: col('sun'),
    sunI: mix('sunI'),
    moonI: Math.max(0, (s - 0.74) / 0.26) * 0.9,
    hemiSky: col('hemiSky'),
    hemiGround: col('hemiGround'),
    hemiI: mix('hemiI'),
    table: col('table'),
    wash: mix('wash'),
    dark: mix('dark'),
  }
}
const phaseName = (s) =>
  s < 0.26 ? 'Afternoon' : s < 0.56 ? 'Golden hour' : s < 0.84 ? 'Dusk' : 'Night'

/* The table's contour pattern: decoration, drawn once. It is not a map of anything. */
function makeTopoPattern() {
  const n = 512
  const c = document.createElement('canvas')
  c.width = c.height = n
  const g = c.getContext('2d')
  const img = g.createImageData(n, n)
  let seed = 11
  const rnd = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646
  const hills = Array.from({ length: 14 }, () => [
    rnd(),
    rnd(),
    0.08 + rnd() * 0.2,
    0.4 + rnd() * 0.9,
  ])
  const field = new Float32Array(n * n)
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      let v = 0
      for (const [hx, hy, r, a] of hills) {
        const dx = Math.min(Math.abs(x / n - hx), 1 - Math.abs(x / n - hx))
        const dy = Math.min(Math.abs(y / n - hy), 1 - Math.abs(y / n - hy))
        v += a * Math.exp(-(dx * dx + dy * dy) / (r * r))
      }
      field[y * n + x] = v
    }
  }
  const levels = 11
  for (let y = 0; y < n - 1; y++) {
    for (let x = 0; x < n - 1; x++) {
      const q = Math.floor(field[y * n + x] * levels)
      const edge =
        q !== Math.floor(field[y * n + x + 1] * levels) ||
        q !== Math.floor(field[(y + 1) * n + x] * levels)
      const i = (y * n + x) * 4
      img.data[i] = img.data[i + 1] = img.data[i + 2] = 255
      img.data[i + 3] = edge ? (q % 5 === 0 ? 255 : 150) : 0
    }
  }
  g.putImageData(img, 0, 0)
  return c
}

function makeTableTexture() {
  const c = document.createElement('canvas')
  c.width = 1536
  c.height = 1024
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function Table({ atmo }) {
  const [tex] = useState(makeTableTexture)
  const [topo] = useState(makeTopoPattern)
  const live = useRef(null)
  useEffect(() => {
    if (!live.current) return
    const c = live.current.image
    const g = c.getContext('2d')
    const { width: w, height: h } = c
    g.globalAlpha = 1
    g.fillStyle = `#${atmo.table.getHexString()}`
    g.fillRect(0, 0, w, h)
    if (atmo.wash > 0.01) {
      // the low sun warms the western side of the table
      const rg = g.createRadialGradient(-w * 0.1, h * 0.62, 0, -w * 0.1, h * 0.62, w * 0.95)
      rg.addColorStop(0, `rgba(226,150,82,${0.5 * atmo.wash})`)
      rg.addColorStop(0.35, `rgba(170,98,62,${0.24 * atmo.wash})`)
      rg.addColorStop(1, 'rgba(120,70,60,0)')
      g.fillStyle = rg
      g.fillRect(0, 0, w, h)
    }
    g.globalAlpha = 0.085 - atmo.dark * 0.03
    g.imageSmoothingEnabled = true
    g.drawImage(topo, 0, 0, w, h)
    g.globalAlpha = 1
    // the page colour takes over at the foot of the stage
    const foot = g.createLinearGradient(0, h * 0.8, 0, h)
    foot.addColorStop(0, 'rgba(15,23,20,0)')
    foot.addColorStop(1, 'rgba(15,23,20,1)')
    g.fillStyle = foot
    g.fillRect(0, h * 0.8, w, h * 0.2)
    live.current.needsUpdate = true
  }, [atmo, topo])
  return <primitive ref={live} attach="background" object={tex} />
}

function SunLight({ atmo, coarse }) {
  const sun = useRef()
  const size = coarse ? 1024 : 2048
  useEffect(() => {
    if (!sun.current) return
    // never let the shadow-casting light drop so low that one ridge blacks out a state
    const dir = atmo.sunDir.clone()
    dir.y = Math.max(dir.y, 0.22)
    sun.current.position.copy(dir.normalize().multiplyScalar(160))
    sun.current.target.position.set(0, 0, 0)
    sun.current.target.updateMatrixWorld()
  }, [atmo])
  return (
    <>
      <hemisphereLight args={[atmo.hemiSky, atmo.hemiGround, atmo.hemiI]} />
      <directionalLight
        ref={sun}
        color={atmo.sun}
        intensity={atmo.sunI}
        castShadow
        shadow-mapSize={[size, size]}
        shadow-bias={-0.0005}
        shadow-normalBias={0.35}
        shadow-radius={3}
      >
        <orthographicCamera attach="shadow-camera" args={[-72, 72, 64, -64, 20, 360]} />
      </directionalLight>
      <directionalLight position={[60, 80, 35]} color={MOON} intensity={atmo.moonI} />
      {/* the table: invisible but for the shadow the model throws on it */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.7, 0]} receiveShadow>
        <planeGeometry args={[420, 320]} />
        <shadowMaterial transparent opacity={0.5} />
      </mesh>
    </>
  )
}

/* ---------- the park markers ---------- */
/* A survey mark on a pin: a small diamond held above the ground, the same on-screen size
 * at any zoom. Cream by default, ember when chosen. No glow: the model is lit, not the pins. */
function makeMark(fill, edge) {
  const c = document.createElement('canvas')
  c.width = c.height = 96
  const g = c.getContext('2d')
  g.translate(48, 48)
  g.rotate(Math.PI / 4)
  g.fillStyle = edge
  g.fillRect(-27, -27, 54, 54)
  g.fillStyle = fill
  g.fillRect(-19, -19, 38, 38)
  g.fillStyle = edge
  g.fillRect(-5, -5, 10, 10)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}
function useMarks() {
  return useMemo(
    () => ({ rest: makeMark('#F4EAD4', '#14261D'), chosen: makeMark('#F2B45A', '#1A1408') }),
    []
  )
}

function Marker({ frame, park, index, active, hovered, still, marks, groundAt, k }) {
  const [x, z] = frame.project(park.lat, park.lng)
  const y = groundAt(park.lat, park.lng)
  const group = useRef()
  const head = useRef()
  const t0 = useRef(null)
  const stem = 1.25
  useFrame(({ clock }) => {
    if (!group.current) return
    let s = 1
    if (!still) {
      if (t0.current === null) t0.current = clock.elapsedTime
      const p = Math.min(
        1,
        Math.max(0, (clock.elapsedTime - t0.current - 2.3 - index * 0.035) / 0.5)
      )
      s = 1 - Math.pow(1 - p, 3)
    }
    group.current.visible = s > 0.001
    // the pin drops in from above and lands
    group.current.position.y = (1 - s) * 5
    if (head.current) {
      const want = (active ? 0.022 : hovered ? 0.018 : 0.0135) * k * Math.max(0.001, s)
      const cur = head.current.scale.x
      head.current.scale.setScalar(cur + (want - cur) * 0.2)
    }
  })
  return (
    <group position={[x, y, z]}>
      <group ref={group}>
        <mesh position={[0, stem / 2, 0]}>
          <cylinderGeometry args={[0.022, 0.022, stem, 5]} />
          <meshBasicMaterial
            color={active ? '#F2B45A' : '#F4EAD4'}
            transparent
            opacity={0.85}
            toneMapped={false}
          />
        </mesh>
        <sprite ref={head} position={[0, stem, 0]} scale={[0.0135 * k, 0.0135 * k, 1]}>
          <spriteMaterial
            map={active ? marks.chosen : marks.rest}
            sizeAttenuation={false}
            depthTest={false}
            transparent
            toneMapped={false}
          />
        </sprite>
      </group>
      {(hovered || active) && (
        <Html
          position={[0, stem + 0.9, 0]}
          center
          zIndexRange={[20, 0]}
          style={{ pointerEvents: 'none' }}
        >
          <span className={`parksmap-label${active ? ' is-active' : ''}`}>{shortName(park)}</span>
        </Html>
      )}
    </group>
  )
}

function Markers({ frame, parks, selected, hover, still, groundAt }) {
  const marks = useMarks()
  // on a narrow screen the model is small, so the marks shrink with it
  const { size } = useThree()
  const k = Math.min(1, Math.max(0.5, size.width / 1000))
  return parks.map((p, i) => (
    <Marker
      key={p.code}
      frame={frame}
      park={p}
      index={i}
      active={p.code === selected}
      hovered={p.code === hover}
      still={still}
      marks={marks}
      groundAt={groundAt}
      k={k}
    />
  ))
}

/* ---------- camera ---------- */
const HOME_DIR = new THREE.Vector3(0, 0.74, 0.67).normalize()
/** The home view. On a wide screen the model sits right of the title; on a tall one, under it. */
function homeView(camera, size, frame) {
  const half = Math.tan((camera.fov * Math.PI) / 360)
  const aspect = size.width / size.height
  const wide = aspect > 1.25
  const share = wide ? 0.6 : 0.96 // how much of the width the model may take
  // a region that is deep north to south (Alaska, Hawaii) needs more room top and bottom
  const deep = frame.D > 60
  const dist = Math.max(
    W / (2 * half * aspect * share),
    (frame.D * (deep ? 1.62 : 1.45)) / (2 * half)
  )
  const visibleW = 2 * half * aspect * dist
  return {
    dist,
    x: wide ? -visibleW * 0.17 : 0,
    z: -dist * (wide ? (deep ? 0.015 : 0.07) : deep ? 0.05 : 0.09),
  }
}

function Rig({ frame, focus, still, coarse, groundAt }) {
  const controls = useRef()
  const { camera, size } = useThree()
  const want = useRef({
    target: new THREE.Vector3(),
    offset: new THREE.Vector3(),
    moving: true,
    first: true,
    slow: false,
  })
  useEffect(() => {
    const w = want.current
    if (focus) {
      w.slow = false
      const [x, z] = frame.project(focus.lat, focus.lng)
      w.offset.set(0, 20, 21)
      // on a wide screen the park card covers the right side, so the park sits left of centre
      const aspect = size.width / size.height
      const visibleW = 2 * Math.tan((camera.fov * Math.PI) / 360) * aspect * w.offset.length()
      w.target.set(x + (aspect > 1.25 ? visibleW * 0.16 : 0), groundAt(focus.lat, focus.lng), z)
    } else {
      const home = homeView(camera, size, frame)
      w.target.set(home.x, 0, home.z)
      w.offset.copy(HOME_DIR).multiplyScalar(home.dist)
    }
    w.moving = true
  }, [frame, focus, camera, size, groundAt])
  useFrame((_, dt) => {
    const c = controls.current
    if (!c) return
    const w = want.current
    if (w.moving) {
      if (w.first && !still && !focus) {
        // open from high overhead, then settle to the home angle
        const d = w.offset.length() * 1.3
        c.target.copy(w.target)
        camera.position.copy(w.target).add(new THREE.Vector3(0, 0.995, 0.1).multiplyScalar(d))
        w.first = false
        w.slow = true
      }
      // time-based, so a slow device takes the same seconds as a fast one
      const k = still || w.first ? 1 : 1 - Math.exp(-Math.min(dt, 0.25) * (w.slow ? 1.3 : 4))
      w.first = false
      c.target.lerp(w.target, k)
      const goal = w.target.clone().add(w.offset)
      camera.position.lerp(goal, k)
      if (camera.position.distanceTo(goal) < 0.05) {
        w.moving = false
        w.slow = false
      }
    }
    c.update()
  })
  return (
    <OrbitControls
      ref={controls}
      enabled={!coarse}
      enablePan={false}
      enableZoom={false} /* the page must keep its scroll wheel */
      enableDamping
      dampingFactor={0.08}
      minPolarAngle={0.35}
      maxPolarAngle={1.12}
      minAzimuthAngle={-0.6}
      maxAzimuthAngle={0.6}
      onStart={() => {
        want.current.moving = false
      }}
    />
  )
}

/* One picker for the whole canvas: the marker nearest the pointer in SCREEN space wins.
 * Per-marker hit meshes failed where parks cluster (a click on Yellowstone chose Grand
 * Teton, whose target stood in front of it). A drag never selects. */
const PICK_LIFTS = [0.1, 0.65, 1.25]
function Picker({ frame, parks, onHover, onSelect, groundAt }) {
  const { camera, gl, size } = useThree()
  useEffect(() => {
    const el = gl.domElement
    const v = new THREE.Vector3()
    const nearest = (e) => {
      const r = el.getBoundingClientRect()
      const px = e.clientX - r.left
      const py = e.clientY - r.top
      let best = null
      let bestD = 30
      for (const p of parks) {
        const [x, z] = frame.project(p.lat, p.lng)
        const g = groundAt(p.lat, p.lng)
        for (const lift of PICK_LIFTS) {
          v.set(x, g + lift, z).project(camera)
          const d = Math.hypot(
            ((v.x + 1) / 2) * size.width - px,
            ((1 - v.y) / 2) * size.height - py
          )
          if (d < bestD) {
            bestD = d
            best = p.code
          }
        }
      }
      return best
    }
    let down = null
    const move = (e) => onHover(e.pointerType === 'touch' ? null : nearest(e))
    const leave = () => onHover(null)
    const press = (e) => {
      down = [e.clientX, e.clientY]
    }
    const release = (e) => {
      if (!down) return
      const dragged = Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 6
      down = null
      if (dragged) return
      const hit = nearest(e)
      if (hit) onSelect(hit)
    }
    el.addEventListener('pointermove', move)
    el.addEventListener('pointerleave', leave)
    el.addEventListener('pointerdown', press)
    el.addEventListener('pointerup', release)
    return () => {
      el.removeEventListener('pointermove', move)
      el.removeEventListener('pointerleave', leave)
      el.removeEventListener('pointerdown', press)
      el.removeEventListener('pointerup', release)
    }
  }, [frame, camera, gl, size, parks, onHover, onSelect, groundAt])
  return null
}

/* ?debug exposes each marker's screen position so a browser test can click the real thing. */
function DebugProbe({ frame, parks, groundAt }) {
  const { camera, size } = useThree()
  useEffect(() => {
    if (!/[?&]debug\b/.test(window.location.search)) return undefined
    window.__parksScreen = (code) => {
      const p = parks.find((q) => q.code === code)
      if (!p) return null
      const [x, z] = frame.project(p.lat, p.lng)
      const v = new THREE.Vector3(x, groundAt(p.lat, p.lng) + 1.25, z).project(camera)
      return { x: ((v.x + 1) / 2) * size.width, y: ((1 - v.y) / 2) * size.height }
    }
    return () => {
      delete window.__parksScreen
    }
  }, [frame, camera, size, parks, groundAt])
  return null
}

/* Everything that belongs to one region. Keyed by region, so switching builds a fresh
 * model that rises the same way the first one did. */
function Model({ frame, parks, selected, hover, hinted, still, coarse, onHover, onSelect }) {
  const relief = useRelief(frame)
  const lines = useStateLines(frame, relief)
  const parkBounds = useParkBounds(frame, relief)
  // west to east: the pins land the way the last light crosses the country
  const here = useMemo(
    () => parks.filter((p) => p.region === frame.id).sort((a, b) => a.lng - b.lng),
    [parks, frame]
  )
  const focus = here.find((p) => p.code === selected) || null
  if (!relief) return null
  return (
    <>
      <Terrain
        frame={frame}
        relief={relief}
        step={coarse ? 2 : 1}
        still={still}
        lines={lines}
        parkBounds={parkBounds}
        activeCode={selected || hover || hinted}
      />
      {!coarse && <Slab frame={frame} relief={relief} />}
      <Markers
        frame={frame}
        parks={here}
        selected={selected}
        hover={hover || hinted}
        still={still}
        groundAt={relief.groundAt}
      />
      <Rig frame={frame} focus={focus} still={still} coarse={coarse} groundAt={relief.groundAt} />
      <Picker
        frame={frame}
        parks={here}
        onHover={onHover}
        onSelect={onSelect}
        groundAt={relief.groundAt}
      />
      <DebugProbe frame={frame} parks={here} groundAt={relief.groundAt} />
    </>
  )
}

function canWebGL() {
  try {
    const c = document.createElement('canvas')
    return !!(c.getContext('webgl2') || c.getContext('webgl'))
  } catch {
    return false
  }
}

const DUSK = 0.6

export default function ParksMap({ parks, region, selected, onSelect, hinted }) {
  const frame = FRAMES[region] || FRAMES.lower48
  const [hover, setHover] = useState(null)
  const [ok] = useState(canWebGL)
  const still = useMemo(
    () =>
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  )
  const coarse = useMemo(
    () => typeof window !== 'undefined' && window.matchMedia('(pointer: coarse)').matches,
    []
  )
  const [sun, setSun] = useState(still ? DUSK : 0.24)
  const touched = useRef(false)
  const atmo = useMemo(() => atmosphere(sun), [sun])

  // The one orchestrated moment: as the land rises, the afternoon runs down toward dusk.
  useEffect(() => {
    if (still) return undefined
    let raf
    const t0 = window.performance.now()
    const tick = (now) => {
      if (touched.current) return
      const p = Math.min(1, Math.max(0, (now - t0 - 900) / 3600))
      setSun(0.24 + (DUSK - 0.24) * (1 - Math.pow(1 - p, 2)))
      if (p < 1) raf = window.requestAnimationFrame(tick)
      else touched.current = true
    }
    raf = window.requestAnimationFrame(tick)
    return () => window.cancelAnimationFrame(raf)
  }, [still])

  const moveSun = useCallback((e) => {
    touched.current = true
    setSun(Number(e.target.value) / 1000)
  }, [])

  if (!ok) {
    return (
      <div className="parksmap parksmap--flat" role="note">
        This device can&rsquo;t draw the 3D map. Every park is in the index below.
      </div>
    )
  }
  return (
    <div className={`parksmap${hover ? ' is-hovering' : ''}`}>
      <Canvas
        shadows="soft"
        dpr={[1, coarse ? 1.5 : 1.75]}
        camera={{ fov: 32, near: 1, far: 1200, position: [0, 90, 82] }}
        gl={{ antialias: true, powerPreference: 'high-performance' }}
        aria-label={`Relief model of ${frame.label} with a marker on every national park there. The index below the map reaches every park.`}
        role="img"
      >
        <Table atmo={atmo} />
        <SunLight atmo={atmo} coarse={coarse} />
        <Model
          key={frame.id}
          frame={frame}
          parks={parks}
          selected={selected}
          hover={hover}
          hinted={hinted}
          still={still}
          coarse={coarse}
          onHover={setHover}
          onSelect={onSelect}
        />
        {!coarse && (
          <EffectComposer multisampling={4}>
            <N8AO aoRadius={1.4} intensity={1.5} distanceFalloff={1.2} quality="medium" />
            <TiltShift2 blur={0.04} />
            <Vignette offset={0.3} darkness={0.55} />
            <Noise opacity={0.03} />
          </EffectComposer>
        )}
      </Canvas>
      <label className="parksmap-sun">
        <span className="pk-sr">Time of day, from afternoon to night</span>
        <input
          type="range"
          min="0"
          max="1000"
          step="1"
          value={Math.round(sun * 1000)}
          onChange={moveSun}
          aria-valuetext={phaseName(sun)}
        />
      </label>
    </div>
  )
}
